//go:build arm64

package floats

// Horner and Clenshaw kernels generated by go-asmgen (polyval_arm64_gen.go) into
// polyval_arm64.s: VFMUL, VFADD, VFSUB, no VFMLA. NEON is the ARMv8-A baseline,
// so there is no runtime gate. The callers pass dst and x sliced to the same
// length n >= 1; the Chebval kernel requires len(c) >= 2. Neither keeps a
// pointer.
//
//go:noescape
func polyvalNEON(dst, x, c []float64)

//go:noescape
func chebvalNEON(dst, x, c []float64)

func polyvalKernel(dst, x, c []float64) { polyvalNEON(dst, x, c) }
func chebvalKernel(dst, x, c []float64) { chebvalNEON(dst, x, c) }
